function getNext7Days() {
  const days = [];
  const now = new Date();
  const DOW = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
  const MON = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  for (let i = 0; i < 7; i++) {
    const d = new Date(now);
    d.setDate(now.getDate() + i);
    days.push({
      dow: DOW[d.getDay()],
      d: d.getDate(),
      mon: MON[d.getMonth()],
      full: `${DOW[d.getDay()]}, ${d.getDate()} ${MON[d.getMonth()]} ${d.getFullYear()}`,
      date: d,
      isToday: i === 0,
    });
  }
  return days;
}

function getAvailableTimes() {
  const now = new Date();
  const h = now.getHours(), m = now.getMinutes();
  const allSlots = [9,10,11,12,14,15,16,17];
  // minimum 1hr ahead; if past 2:30pm only 4pm-6pm available
  const minH = h + (m > 0 ? 1 : 0) + 1;
  const cutoff = (h > 14 || (h === 14 && m >= 30)) ? 16 : 0;
  const todaySlots = [];
  allSlots.forEach(slot => {
    if (slot >= minH && slot <= 17 && slot >= cutoff) {
      const label = slot < 12 ? `${slot}:00 AM` : slot === 12 ? "12:00 PM" : `${slot-12}:00 PM`;
      todaySlots.push({ label, today: true });
    }
  });
  return todaySlots;
}

function genCode() {
  return "RIVA-" + Math.random().toString(36).substr(2,4).toUpperCase() + "-" + Date.now().toString().slice(-4);
}

