  const sendOtp = () => {
    if (!form.name.trim()) { setOtpErr("Please enter your full name."); return; }
    if (form.hp.replace(/\D/g,"").length < 9) { setOtpErr("Please enter a valid phone number."); return; }
    if (!form.location.trim()) { setOtpErr("Please enter your current staying location."); return; }
    setOtpErr(""); setRegStep(2);
  };
  const verifyOtp = () => {
    if (otp === "8823") { setOtpErr(""); setRegStep(3); }
    else setOtpErr("Invalid OTP. (Demo: 8823)");
  };
  const confirmAppt = () => {
    if (!bForm.date || !bForm.time) return;
    const code = genCode();
    setApptCode(code);
    setBDone(true);
  };

